use crate::prelude::internal::*;

mod file;
pub use file::*;

#[derive(Debug, PartialEq, Clone, Serialize)]
pub struct GtlDist {
    pub files: Vec<GtlDistFile>,
    pub modules: Vec<GtlDistModule>,
    pub diagnostics: Vec<GtDiagnostic>,
}

#[derive(Debug, PartialEq, Clone, Serialize)]
pub struct GtlDistModule {
    pub source_path: GtpModulePath,
    pub target_path: GtpTargetFilePath,
}

impl GtlDist {
    pub fn new<ProjectModule: GtlProjectModule>(
        generations: Vec<GtlGeneration<ProjectModule>>,
        diagnostics: Vec<GtDiagnostic>,
    ) -> GtlDist {
        let mut dist = GtlDist {
            files: vec![],
            modules: vec![],
            diagnostics,
            // info: BTreeMap::new(),
        };
        for generation in generations {
            dist.pack_generation(generation);
        }
        dist
    }

    pub fn pack_extra_files<ProjectModule: GtlProjectModule>(
        &mut self,
        extra_files: Vec<GtlGeneration<ProjectModule>>,
        extra_diagnostics: Option<Vec<GtDiagnostic>>,
    ) {
        for extra in extra_files {
            self.pack_generation(extra);
        }

        if let Some(extra_diagnostics) = extra_diagnostics {
            self.diagnostics.extend(extra_diagnostics);
        }
    }

    pub fn sort_files(&mut self) {
        self.files.sort_by(|a, b| a.path().cmp(b.path()));
    }

    pub(crate) fn validate_target_paths(&self) -> Result<(), GtlProjectError> {
        let mut path_counts: IndexMap<&GtpTargetFilePath, usize> = IndexMap::new();
        for file in &self.files {
            *path_counts.entry(file.path()).or_default() += 1;
        }

        let mut collisions = path_counts
            .into_iter()
            .filter(|(_, count)| *count > 1)
            .map(|(path, count)| {
                let source_paths = self
                    .modules
                    .iter()
                    .filter(|module| &module.target_path == path)
                    .map(|module| format!("`{}`", module.source_path))
                    .collect::<Vec<_>>();
                let generated_count = count.saturating_sub(source_paths.len());

                let mut origins = source_paths;
                origins
                    .extend((0..generated_count).map(|_| "a synthetic project file".to_string()));

                format!(
                    "- Target path `{path}` is generated by {}",
                    origins.join(" and ")
                )
            })
            .collect::<Vec<_>>();
        collisions.sort();

        if collisions.is_empty() {
            Ok(())
        } else {
            Err(GtlProjectError::TargetPathCollision {
                details: collisions.join("\n"),
            })
        }
    }

    fn pack_generation<ProjectModule: GtlProjectModule>(
        &mut self,
        generation: GtlGeneration<ProjectModule>,
    ) {
        if let GtlProjectFile::Module(GtlProjectModuleState::Rendered(rendered)) = &generation.file
        {
            let converted = rendered.converted();
            self.modules.push(GtlDistModule {
                source_path: converted.source_path.clone(),
                target_path: converted.target_path.clone(),
            });
        }

        let file: GtlDistFile = generation.file.into();

        self.files.push(file);
        if let Some(diagnostics) = generation.diagnostics {
            self.diagnostics.extend(diagnostics);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn generated_file(path: &str) -> GtlDistFile {
        GtlDistFile::Generated(GtlDistFileGenerated {
            path: path.into(),
            source_code: GtpSourceCode::new(String::new()),
            source_module_id: None,
        })
    }

    #[test]
    fn validates_unique_target_paths() {
        let dist = GtlDist {
            files: vec![generated_file("dist/ts/foo.ts")],
            modules: vec![],
            diagnostics: vec![],
        };

        assert_eq!(dist.validate_target_paths(), Ok(()));
    }

    #[test]
    fn reports_module_target_path_collisions() {
        let target_path = GtpTargetFilePath::from("dist/ts/fooBar.ts");
        let dist = GtlDist {
            files: vec![
                generated_file(target_path.as_str()),
                generated_file(target_path.as_str()),
            ],
            modules: vec![
                GtlDistModule {
                    source_path: "src/fooBar.type".into(),
                    target_path: target_path.clone(),
                },
                GtlDistModule {
                    source_path: "src/foo_bar.type".into(),
                    target_path,
                },
            ],
            diagnostics: vec![],
        };

        insta::assert_snapshot!(
            dist.validate_target_paths().unwrap_err().to_string(),
            @r#"
        Generated file name collisions detected:
        - Target path `dist/ts/fooBar.ts` is generated by `src/fooBar.type` and `src/foo_bar.type`
        "#
        );
    }

    #[test]
    fn reports_generated_file_target_path_collisions() {
        let target_path = GtpTargetFilePath::from("dist/ts/index.ts");
        let dist = GtlDist {
            files: vec![
                generated_file(target_path.as_str()),
                generated_file(target_path.as_str()),
            ],
            modules: vec![GtlDistModule {
                source_path: "src/Index.type".into(),
                target_path,
            }],
            diagnostics: vec![],
        };

        insta::assert_snapshot!(
            dist.validate_target_paths().unwrap_err().to_string(),
            @"
        Generated file name collisions detected:
        - Target path `dist/ts/index.ts` is generated by `src/Index.type` and a synthetic project file
        "
        );
    }
}
